import java.util.*;import java.awt.*;import java.awt.image.*;import java.io.*;import javax.imageio.ImageIO;
import com.koios.game.arpg.*;import com.koios.game.model.*;import com.koios.game.model.player.*;import com.koios.game.map.*;import com.koios.network.*;import com.koios.game.content.combat.CombatVariables.AttackType;
public class ExpansionCheck {
 static int checks;static void check(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
 static void rejects(Runnable action){try{action.run();throw new AssertionError("Expected rejection");}catch(IllegalArgumentException expected){checks++;}}
 public static void main(String[] args)throws Exception{
  PrototypeIntegrationCheck.loaded();SkillState state=new SkillState();rejects(()->state.attach(0,0,true));state.learnSupport(0,1,1);state.attach(0,0,true);check(state.available(0)==0,"One gem supplies one attached support");rejects(()->state.attach(1,0,true));state.moveSupport(0,3,0);check(state.getSupport(0)==0&&state.getSupport(3)==1,"Support moves to expanded skill without duplication");state.attach(3,0,false);check(state.available(0)==1,"Removing returns support to library");state.clear(0);state.clear(1);state.clear(2);check(state.saveHotbar().equals("-1,-1,-1"),"All hotbar slots can be empty");state.assign(1,4);check(state.assigned(0)==-1&&state.assigned(1)==4&&state.assigned(2)==-1,"New skill does not populate unrelated slots");SkillState restored=new SkillState();restored.loadHotbar(state.saveHotbar());restored.loadOwned(state.saveOwned());check(restored.saveHotbar().equals(state.saveHotbar())&&restored.available(0)==1,"Empty slots and gem ownership persist");SkillState legacy=new SkillState();legacy.setSupport(0,7);legacy.reconcileOwnership();check(legacy.getSupport(0)==0,"Old automatic supports cannot bypass gem ownership");
  com.koios.client.arpg.SkillDragState drag=new com.koios.client.arpg.SkillDragState();String[] view=state.update(50).split("\\|");drag.begin(45,154,view);check(drag.kind==5&&drag.origin==1&&drag.skill==4,"Only the three socketed active gems can begin a loadout drag");drag.cancel();drag.begin(350,85,view);check(!drag.active(),"Removed skill/support libraries expose no phantom draggables");
  Player socketer=PrototypeIntegrationCheck.player("socketer",29);socketer.setAttribute("tutorial-stage",11);PrototypeIntegrationCheck.idle(socketer);socketer.getInventory().set(0,MapRuns.gem(1,false,0));socketer.getInventory().set(1,MapRuns.gem(1,true,1));ArpgSkills.handle(socketer,"arpgskill socketactive 0 0");check(socketer.getInventory().get(0)==null&&socketer.getArpgSkills().assigned(0)==0,"Active gem occupies one of three limited loadout sockets");ArpgSkills.handle(socketer,"arpgskill socket 1 0 0");check(socketer.getInventory().get(1)==null&&socketer.getArpgSkills().getSupport(0)==2,"Inventory support gem attaches to the socketed active skill");ArpgSkills.handle(socketer,"arpgskill unsocket 0 1");check(socketer.getArpgSkills().getSupport(0)==0&&socketer.getInventory().getValidItems().stream().anyMatch(item->MapRuns.isGem(item)&&item.getRoll().getGem().support),"Socketed support returns to inventory as a gem item");ArpgSkills.handle(socketer,"arpgskill unsocketactive 0");check(socketer.getArpgSkills().assigned(0)==-1&&socketer.getInventory().getValidItems().stream().anyMatch(item->MapRuns.isGem(item)&&!item.getRoll().getGem().support&&item.getRoll().getGem().kind==0),"Active gem returns to inventory with its identity");
  BufferedImage preview=new BufferedImage(840,430,BufferedImage.TYPE_INT_RGB);Graphics2D graphics=preview.createGraphics();graphics.setColor(new Color(0x10191F));graphics.fillRect(0,0,840,430);
  for(int layout=1;layout<=2;layout++){
   Player p=PrototypeIntegrationCheck.player("layout"+layout,20+layout);p.setAttribute("starter-claimed",true);p.setAttribute("intro-complete",true);p.setAttribute("tutorial-stage",11);MapRuns.home(p);PrototypeIntegrationCheck.idle(p);p.getInventory().set(0,MapRuns.map(2,0,layout));MapRuns.start(p,0,false);PrototypeIntegrationCheck.idle(p);MapRuns.Run run=MapRuns.run(p);check(run.layout==layout&&run.region.scenery.size()>100,"Custom layout has authored scenery");check(run.mobs.size()==19,"Custom map populates encounter packs and boss");Set<Long> reachable=new HashSet<>();for(Location cell:MapRuns.reachable(run.spawn,60))reachable.add(((long)cell.getX()<<32)|(cell.getY()&0xffffffffL));for(MapRuns.MapMob mob:run.mobs)check(reachable.contains(((long)mob.getX()<<32)|(mob.getY()&0xffffffffL)),"Every enemy is reachable through the rooms");check(MapRegion.getClipping(run.region.baseX+31,run.region.baseY+52,0)!=0,"Arena boundaries block escape");MapRuns.fixtures(p);check(((PrototypeIntegrationCheck.SessionStub)p.getSession()).packets.stream().anyMatch(packet->packet.getOpcode()==151),"Authored scenery is sent to client");
   p.getEquipment().set(3,AffixCatalog.starter(true));MapRuns.MapMob boss=run.mobs.get(18);for(Location cell:MapRuns.reachable(boss.getLocation(),1))if(!cell.equals(boss.getLocation())){p.setPosition(cell.copy());break;}PrototypeIntegrationCheck.idle(p);p.getCombat().setAttackType(AttackType.MELEE);p.getCombat().setTarget(boss);p.getArpgSkills().refill(100);ArpgSkills.cast(p,3);check(p.getArpgSkills().getCooldown(3)>0,"Ground Slam executes against a map boss");for(int tick=0;tick<10;tick++)p.getArpgSkills().tick(100,10);ArpgSkills.cast(p,4);check(p.getArpgSkills().getCooldown(4)>0,"Execute has an independent action and cooldown");
   int ox=(layout-1)*420;graphics.setColor(new Color(0xDDC58C));graphics.drawString(AuthoredMaps.name(layout),ox+16,20);for(int x=32;x<=72;x++)for(int y=32;y<=72;y++){graphics.setColor(new Color(MapRegion.getClipping(run.region.baseX+x,run.region.baseY+y,0)==0?0x304537:0x8C8B78));graphics.fillRect(ox+5+(x-32)*10,30+(72-y)*9,9,8);}for(MapRuns.MapMob mob:run.mobs){graphics.setColor(mob==boss?Color.ORANGE:Color.RED);graphics.fillOval(ox+5+(mob.getX()-run.region.baseX-32)*10,30+(72-(mob.getY()-run.region.baseY))*9,6,6);}MapRuns.cleanup(p);
  }
  graphics.dispose();ImageIO.write(preview,"png",new File("build/authored-map-layouts.png"));Set<Integer> baseIds=new HashSet<>();for(EquipmentBases.Base base:EquipmentBases.all())check(baseIds.add(base.itemId),"Equipment base IDs are unique");for(int id:new int[]{22420,22421,22422,22423,22424,22425,22426,22430,22431,22432,22433,22434,22435,22436,22437,22438,22439})check(baseIds.contains(id),"Expected prototype equipment base registered: "+id);System.out.println("Passed "+checks+" expansion ownership, drag, skill and authored-map checks.");
 }
}

